    def __init__(self, value=0, left=None, right=None):
        self.value = value
        self.left = left
        self.right = right

def is_symmetric(root: Node) -> bool:
    if root is None:
        return True

    def _is_mirror(node1: Node, node2: Node) -> bool:
        if node1 is None and node2 is None:
            return True
        if node1 is None or node2 is None:
            return False

        if node1.value != node2.value:
            return False

        # Nested calls for checking mirror symmetry
        if not _is_mirror(node1.left, node2.right):
            return False
        if not _is_mirror(node1.right, node2.left):
            return False
        return True

    return _is_mirror(root.left, root.right)

