def subarray_sum(nums, target_sum):
    current_sum = 0
    start_index = 0

    if not nums:
        return (-1, -1)

    for i, num in enumerate(nums):
        current_sum += num

        while current_sum > target_sum and start_index <= i:
            current_sum -= nums[start_index]
            start_index += 1

        if current_sum == target_sum:
            return (start_index, i)

    return (-1, -1)

