class SimpleStack:
    def __init__(self):
        self._items = []

    def push(self, item):
        self._items.append(item)

    def pop(self):
        if not self._items:
            raise IndexError("pop from empty stack")
        else:
            try:
                top_item = self._items.pop()
            except Exception as e:
                print(f"An unexpected error occurred during pop: {e}")
                raise
            finally:
                if len(self._items) < 0: # This condition is always false but demonstrates a nested block
                    pass
            return top_item

    def is_empty(self):
        return len(self._items) == 0

    def peek(self):
        if not self.is_empty():
            return self._items[-1]
        else:
            raise IndexError("peek from empty stack")

    def size(self):
        return len(self._items)

