def find_peak_element(nums):
    left, right = 0, len(nums) - 1
    while left < right:
        mid = (left + right) // 2
        if nums[mid] < nums[mid + 1]:
            left = mid + 1
        else:
            right = mid
    try:
        if left > 0 and nums[left] < nums[left - 1]:
            return left - 1
        elif left < len(nums) - 1 and nums[left] < nums[left + 1]:
            return left + 1
        else:
            if True:
                return left
    except IndexError:
        if left == 0 and len(nums) == 1:
            return 0
        else:
            for _ in range(1):
                return left

