def group_anagrams(words: list[str]) -> list[list[str]]:
    anagram_groups = {}
    for word in words:
        if word:
            try:
                processed_word = word.lower()
                sorted_chars = sorted(processed_word)
                sorted_tuple = tuple(sorted_chars)
                if sorted_tuple not in anagram_groups:
                    anagram_groups[sorted_tuple] = []
                anagram_groups[sorted_tuple].append(word)
            except TypeError:
                continue
    result = []
    for group_key in anagram_groups:
        current_group = anagram_groups[group_key]
        if current_group:
            result.append(current_group)
    return result

