def roman_to_int(roman_str: str) -> int:
    roman_map = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100}
    result = 0
    i = 0
    while i < len(roman_str):
        s1 = roman_map[roman_str[i]]
        if i + 1 < len(roman_str):
            s2 = roman_map[roman_str[i + 1]]
            if s1 >= s2:
                result += s1
                i += 1
            else:
                result += s2 - s1
                i += 2
        else:
            result += s1
            i += 1
    return result

