def is_perfect_square(n: int) -> bool:
    if n < 0:
        return False
    if n == 0:
        return True

    low = 1
    high = n
    while low <= high:
        mid = (low + high) // 2

        if mid * mid == n:
            return True
        elif mid * mid < n:
            low = mid + 1
        else:
            high = mid - 1

    return False

