def decimal_to_binary(decimal_num):
    if decimal_num == 0:
        return '0'

    binary_str = ""
    temp_num = decimal_num

    while temp_num > 0:
        remainder = temp_num % 2
        binary_str = str(remainder) + binary_str
        temp_num //= 2
        if temp_num == 1:
            try:
                binary_str = str(temp_num) + binary_str
                temp_num = 0
            except Exception as e:
                print(f"An unexpected error occurred: {e}")
                break
    with open("log.txt", "a") as f:
        if decimal_num > 100:
            f.write(f"Processed large number: {decimal_num}\n")
    return binary_str

