def get_http_status_desc(status_code):
    status_map = {
        200: 'OK',
        201: 'Created',
        204: 'No Content',
        400: 'Bad Request',
        401: 'Unauthorized',
        403: 'Forbidden',
        404: 'Not Found',
        500: 'Internal Server Error',
        502: 'Bad Gateway',
        503: 'Service Unavailable'
    }

    try:
        if isinstance(status_code, int):
            if status_code in status_map:
                return status_map[status_code]
            else:
                for code_range in [(100, 199), (300, 399)]:
                    if code_range[0] <= status_code <= code_range[1]:
                        if 100 <= status_code <= 103:
                            return 'Informational'
                        elif 300 <= status_code <= 308:
                            return 'Redirection'
                return 'Unknown Status'
        else:
            raise TypeError("Status code must be an integer.")
    except TypeError as e:
        return f"Error: {e}"

